#if UNITY_EDITOR
using System;
using System.Collections.Generic;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityMeshSimplifier;

/// <summary>
/// Second, non-destructive food-only simplification pass for ImmersiveEye Block C & D.
/// Works with the 32 meshes already generated by ImmersiveEyeFoodMeshOptimizer.
/// Keeps all source mesh assets, materials, transforms, BoxColliders, AOI scripts,
/// interaction scripts and prefab/plate/selection references intact.
/// </summary>
public static class ImmersiveEyeFoodMeshSecondPass
{
    private const string Folder = "Assets/ImmersiveEyeGenerated/OptimizedFoodMeshes_SecondPass";
    private static readonly string[] FoodNames = {
        "White Rice", "Tofu", "StirFry Vege", "Roast Vege",
        "Potato", "Pasta", "Olives", "Nuts", "Fruits", "Fresh Salad",
        "Fish", "Chicken", "Cheese", "Bread", "Beef", "Avocado"
    };

    [MenuItem("Tools/ImmersiveEye/Further Reduce Food Meshes - C and D")]
    public static void Run()
    {
        if (!EditorUtility.DisplayDialog("Further reduce existing optimized food meshes",
            "Creates NEW simplified meshes for 16 food items in each of Blocks C and D. " +
            "Keeps source meshes and ALL food object components/transform references unchanged. " +
            "Do this only after saving a backup copy of your scene. Continue?", "Reduce", "Cancel"))
            return;

        var scene = SceneManager.GetActiveScene();
        var c = Find(scene, "BlockC_Food Items");
        var d = Find(scene, "BlockD_Food Items");
        if (c == null || d == null) {
            Debug.LogError("IMMERSIVEEYE_SECOND_PASS_ERROR: BlockC_Food Items or BlockD_Food Items not found. No changes made.");
            return;
        }

        EnsureFolders();
        int changed = 0, skipped = 0;
        long oldTris = 0, newTris = 0;
        var messages = new List<string>();
        int group = Undo.GetCurrentGroup();
        Undo.SetCurrentGroupName("ImmersiveEye second pass food simplification");
        try {
            foreach (var pair in new [] {
                new KeyValuePair<string, GameObject>("BlockC", c),
                new KeyValuePair<string, GameObject>("BlockD", d)
            }) {
                foreach (string foodName in FoodNames) {
                    string id = pair.Key + "/" + foodName;
                    EditorUtility.DisplayProgressBar("Food mesh second pass", id, (float)(changed + skipped) / 32f);
                    Transform food = pair.Value.transform.Find(foodName);
                    MeshFilter filter = food != null ? food.GetComponent<MeshFilter>() : null;
                    if (filter == null || filter.sharedMesh == null) {
                        messages.Add(id + ": MeshFilter not found"); skipped++; continue;
                    }
                    Mesh before = filter.sharedMesh;
                    if (before.name.StartsWith("ImmersiveEye_FoodLOD2_", StringComparison.Ordinal)) {
                        messages.Add(id + ": already second-pass optimized"); skipped++; continue;
                    }
                    if (!before.name.StartsWith("ImmersiveEye_FoodLOD_", StringComparison.Ordinal)) {
                        messages.Add(id + ": not a first-pass optimized mesh (left untouched)"); skipped++; continue;
                    }
                    try {
                        int originalCount = Triangles(before);
                        var simplifier = new MeshSimplifier();
                        simplifier.Initialize(before);
                        var options = simplifier.SimplificationOptions;
                        // Preserve food texture layout and silhouette edges.
                        options.PreserveUVSeamEdges = true;
                        options.PreserveUVFoldoverEdges = true;
                        options.PreserveBorderEdges = true;
                        simplifier.SimplificationOptions = options;
                        simplifier.SimplifyMesh(0.40f);
                        Mesh reduced = simplifier.ToMesh();
                        reduced.name = "ImmersiveEye_FoodLOD2_" + pair.Key + "_" + foodName.Replace(" ", "_");
                        reduced.RecalculateBounds();
                        int count = Triangles(reduced);
                        if (count <= 0 || count >= originalCount || reduced.subMeshCount != before.subMeshCount) {
                            UnityEngine.Object.DestroyImmediate(reduced);
                            messages.Add(id + ": no valid reduction (kept existing mesh)"); skipped++; continue;
                        }
                        string path = AssetDatabase.GenerateUniqueAssetPath(Folder + "/" + reduced.name + ".asset");
                        AssetDatabase.CreateAsset(reduced, path);
                        Undo.RecordObject(filter, "Reduce food mesh " + id);
                        filter.sharedMesh = reduced;
                        if (PrefabUtility.IsPartOfPrefabInstance(filter))
                            PrefabUtility.RecordPrefabInstancePropertyModifications(filter);
                        EditorUtility.SetDirty(filter);
                        oldTris += originalCount;
                        newTris += count;
                        changed++;
                    }
                    catch (Exception ex) { messages.Add(id + ": " + ex.Message); skipped++; }
                }
            }
        }
        finally {
            EditorUtility.ClearProgressBar();
            AssetDatabase.SaveAssets();
            if (changed > 0) EditorSceneManager.MarkSceneDirty(scene);
            Undo.CollapseUndoOperations(group);
        }
        Debug.Log("IMMERSIVEEYE_SECOND_PASS_RESULT|changed=" + changed + "|skipped=" + skipped +
                  "|oldTriangles=" + oldTris + "|newTriangles=" + newTris +
                  "|inputQuality=0.40|sourceAssetsUnchanged=true|saveScene=true");
        foreach (string msg in messages) Debug.LogWarning("IMMERSIVEEYE_SECOND_PASS_SKIP: " + msg);
    }

    private static void EnsureFolders()
    {
        if (!AssetDatabase.IsValidFolder("Assets/ImmersiveEyeGenerated"))
            AssetDatabase.CreateFolder("Assets", "ImmersiveEyeGenerated");
        if (!AssetDatabase.IsValidFolder(Folder))
            AssetDatabase.CreateFolder("Assets/ImmersiveEyeGenerated", "OptimizedFoodMeshes_SecondPass");
    }
    private static int Triangles(Mesh mesh)
    {
        int count = 0;
        for (int i = 0; i < mesh.subMeshCount; ++i)
            if (mesh.GetTopology(i) == MeshTopology.Triangles)
                count += (int)mesh.GetIndexCount(i) / 3;
        return count;
    }
    private static GameObject Find(Scene scene, string name)
    {
        foreach (GameObject root in scene.GetRootGameObjects())
            foreach (Transform child in root.GetComponentsInChildren<Transform>(true))
                if (child.name == name) return child.gameObject;
        return null;
    }
}
#endif
